  const stateCEmw = isSi ? (res.stateC.emwPpg / 8.33).toFixed(3) : res.stateC.emwPpg.toFixed(2);
  const stateCSafety = isSi ? (res.stateC.safetyPsi / 14.5038).toFixed(1) : Math.round(res.stateC.safetyPsi).toLocaleString();
